insert into public.grants (id, rule_key, name, body, level, category, amount_text, max_amount, window_state, opens, closes, next_call, paid, summary, covers, obligations, docs, steps, source_url, official_ref, verified_at, verification_note, hidden_reason, fee_trigger, selectable, active, sort_order) values
('equipos-hosteleria','equipos_hosteleria','Hospitality equipment renewal (RD 638/2026)','Ministerio de Industria y Turismo','national','energy','€5,000 to €11,000 per establishment, up to 100% of cost (excl. IVA)',11000,'open','2026-08-05','2026-09-30','A one-off emergency plan. No further call announced.','Paid in order of complete applications until the €15M budget runs out, so incomplete applications lose their place. After approval you have 1 month to install and 15 days to justify. Costs from 1 March 2026 can count.','Replace old catering equipment, AC units, awnings or terrace umbrellas with more efficient models. It pays up to 100%, so it can cost you nothing.',array['Catering equipment: induction hobs, electric ovens and fryers, dishwashers, glass washers, blast chillers','Refrigeration: cold rooms, freezers, fridges, refrigerated counters and display cabinets, ice makers','Industrial coffee machines','AC units, awnings and terrace umbrellas','Installation, removal of the old equipment and the energy certificate','Managing the application (up to 4%) and the justification (up to 7%)']::text[],array['Replace existing equipment, not add new equipment.','No gas or other fossil-fuel equipment.','Install within 1 month of approval and justify within 15 days.','Don’t claim the same costs from another grant.']::text[],array['Digital certificate of the legal representative, plus AutoFirma','Project description (memoria)','Proof of the energy saving','CNAE code','Invoice or detailed quote for the new equipment','Energy efficiency certificate from a qualified technician']::text[],array['List the equipment to replace and get quotes for more efficient models.','Prepare the project description and proof of the energy saving.','Apply on the Ministry’s Portal de Ayudas before 30 Sep 2026 at 15:00.','Once approved, install within 1 month.','Justify within 15 days with invoices, proof of payment, energy labels and the waste certificate.']::text[],'https://www.mintur.gob.es/PortalAyudas/EquiposHosteleria',null,'2026-09-23','Checked against BOE and the Ministry’s applicant guide.',null,'payment',true,true,10),
('cuota-cero','cuota_cero','Cuota Cero (Línea 1)','Junta de Andalucía, Empleo','regional','autonomo','About €1,000: a full refund of 12 months of tarifa plana',1000,'open',null,'2026-09-30','This call ends 30 Sep 2026. Watch for the next one.','Refund paid to your bank account after approval.','The Junta refunds the €80-a-month tarifa plana you paid in your first year, so your first 12 months of Social Security cost nothing.',array['Your autónomo Social Security quota for 12 months (24 if your income stays under the minimum wage)']::text[],array['Stay registered as autónomo for 12 months.']::text[],array['Digital certificate or Cl@ve','Bank account (IBAN) in your name']::text[],array['Finish your 12 months on the tarifa plana.','Open “Subvenciones Línea 1. Cuota cero” on the Junta de Andalucía e-office.','Enter your details and bank account and sign. No attachments: the Junta checks your records itself.','Receive the refund once approved.']::text[],'https://www.juntadeandalucia.es/organismos/empleoempresaytrabajoautonomo/areas/trabajo-autonomo/fomento-trabajo-autonomo/paginas/subv-fomento-cuota-cero.html',null,'2026-09-23',null,null,'payment',true,true,20),
('linea-2','linea_2','Start-up grant for new autónomos (Línea 2)','Junta de Andalucía, Empleo','regional','autonomo','€3,800 or €5,000 depending on age and gender (up to €5,500 in towns under 10,000)',5500,'open',null,'2026-09-30','This call ends 30 Sep 2026. Watch for the next one.','One-off lump sum, handled in order until the budget runs out.','A one-off payment to help you start out as a new autónomo in Andalucía.',array['General start-up support: you justify it by staying registered, not with receipts']::text[],array['Stay registered as autónomo for 12 months in a row.','Don’t work as an employee for more than 25% of that period.','Stay up to date with Hacienda, Social Security and the Junta.','Keep the paperwork for 5 years.']::text[],array['Digital certificate or Cl@ve','Viability plan with a provisional profit-and-loss forecast (profit every year)','Proof of RETA registration (resolución de alta)','Bank account (IBAN)']::text[],array['Register as autónomo and request the tarifa plana.','Prepare the viability plan.','Apply within 2 months of registering, and before 30 Sep 2026.','Receive a one-off payment if approved.']::text[],'https://www.juntadeandalucia.es/organismos/empleoempresaytrabajoautonomo/areas/trabajo-autonomo/fomento-trabajo-autonomo/paginas/subv-fomento-inicio-actividad.html',null,'2026-09-23',null,null,'payment',true,true,30),
('kit-digital','kit_digital','Kit Digital (digital voucher)','Red.es, Ministerio para la Transformación Digital','national','digital','€2,000 to €6,000 depending on staff size',6000,'open',null,null,'Runs until the funds are used up.','A voucher spent with an approved digital provider (agente digitalizador), not cash.','A voucher to pay an approved provider for digital tools. You never receive cash.',array['Website and online presence','Online shop','Social media management','Till, booking or management software','Cybersecurity and virtual office tools']::text[],array['Use an approved agente digitalizador.','Keep the solution running for 12 months.']::text[],array['Digital certificate or Cl@ve','Acelera Pyme digital self-assessment test','Proof of being up to date with Hacienda and Social Security']::text[],array['Complete the digital self-assessment on Acelera Pyme.','Apply on the Red.es e-office.','If approved, choose an approved provider and sign the agreement.','The provider delivers (website, e-commerce, social media, POS, cybersecurity) and both sides justify.']::text[],'https://sede.red.gob.es/es/procedimientos/convocatoria-de-ayudas-destinadas-la-digitalizacion-de-empresas-del-segmento-iii',null,'2026-09-23','Extended by Orden TDF/39/2026 until funds run out. Sources disagree on whether applications are open right now and on exact amounts: confirm on Acelera Pyme before applying.','No open call: BOE Orden TDF/39/2026 only extends the programme. Amounts differ between sources. Re-publish when Red.es opens a call.','award',true,false,40),
('talento-joven','talento_joven','Hiring grant: Talento Joven','Cámara de Comercio de Málaga','chamber','hiring','€5,000 per full-time contract',5000,'open',null,'2026-12-31','Watch for the 2027 call.','Paid after you justify the contract. Only 10 grants for 2026, first come first served.','€5,000 when you hire a young person from the Cámara’s Garantía Juvenil programme full-time for at least 6 months.',array['Salary costs of the new hire']::text[],array['Keep the contract full-time for at least 6 months.']::text[],array['Application forms (anexos) from the Cámara de Málaga e-office','Full-time contract of 6 months or more','Proof the hire is in Garantía Juvenil and finished Talento Joven orientation','Certificates of being up to date with Hacienda and Social Security']::text[],array['Confirm the candidate is on the Cámara’s Talento Joven programme.','Sign a full-time contract of at least 6 months.','Apply on the Cámara de Málaga e-office (procedure TR0000006728).','Submit the justification forms to get paid.']::text[],'https://camaramalaga.com/sistema-de-garantia-juvenil-pice-programa-integral-de-cualificacion-y-empleo/convocatoria-ayudas-a-la-contratacion-2026/',null,'2026-09-23',null,null,'payment',true,true,50),
('talento-45','talento_45','Hiring grant: Talento 45+','Cámara de Comercio de Málaga','chamber','hiring','€5,000 per full-time contract',5000,'open',null,'2026-12-31','Watch for the 2027 call.','Paid after you justify the contract. Only 10 grants for 2026, first come first served.','€5,000 when you hire an unemployed person aged 45 to 60 from the Cámara’s Talento 45+ programme full-time for at least 6 months.',array['Salary costs of the new hire']::text[],array['Keep the contract full-time for at least 6 months.']::text[],array['Application forms (anexos) from the Cámara de Málaga e-office','Full-time contract of 6 months or more','Proof the hire is a Talento 45+ participant','Certificates of being up to date with Hacienda and Social Security']::text[],array['Confirm the candidate is on the Cámara’s Talento 45+ programme.','Sign a full-time contract of at least 6 months.','Apply on the Cámara de Málaga e-office (procedure TR0000006723).','Submit the justification forms to get paid.']::text[],'https://camaramalaga.com/sistema-de-garantia-juvenil-pice-programa-integral-de-cualificacion-y-empleo/convocatoria-ayudas-a-la-contratacion-talento-45-2026/',null,'2026-09-23',null,null,'payment',true,true,55),
('inea-empresas','inea','INEA energy incentives for businesses (Programa 2)','Agencia Andaluza de la Energía','regional','energy','Roughly 55% to 65% of eligible cost; projects from about €11,000',0,'open',null,null,'Open until funds run out.','Paid after the installation is justified.','The Junta pays part of energy projects. An approved installer usually handles the application for you.',array['Solar panels and batteries for your own use','Efficient heating, cooling and ventilation','Insulation and efficient lighting']::text[],array['Energy certificates before and after the works, validated independently.']::text[],array['Quote from an approved collaborating company','Energy efficiency certificate before the works','Technical description of the project']::text[],array['Get a quote from a collaborating installer (they usually apply for you).','Apply before starting any works.','Install and get the after-works energy certificate.','Justify and receive the incentive.']::text[],'https://www.agenciaandaluzadelaenergia.es/en/node/3563',null,'2026-09-23','Programme confirmed open. Percentages and minimum project size come from installer sources, not the official text.','Intensity (55–65%) and minimum project size came from installers, and fund availability per line can’t be confirmed on the Agency site. Verify against the official call.','payment',true,false,60),
('pymetur','pymetur','PYMETUR: modernising tourism and hospitality businesses','Junta de Andalucía, Turismo','regional','modernisation','Set in the final rules (not yet published)',0,'upcoming',null,null,'Not open. Only draft rules exist (public consultation, June 2026). The final rules and the call haven’t been published in BOJA yet.','First come, first served (non-competitive) according to the draft rules.','A planned grant for tourism and hospitality SMEs in Andalucía. It will open once the Junta publishes the final rules in BOJA.',array['Modernisation, accessibility and sustainability of tourism businesses (per the draft; final scope set by the approved rules)']::text[],array['Projects must not start before applying.']::text[],array['Registration in the Registro de Turismo de Andalucía','IAE registration','Project description and budget','Certificates of being up to date with Hacienda and Social Security']::text[],array['Make sure the business is in the Registro de Turismo de Andalucía.','Plan the project (modernisation, accessibility, sustainability, climate adaptation or quality certification) and get quotes.','Apply when the call opens, before starting works.']::text[],'https://www.juntadeandalucia.es/boja/2026/109/28','BOJA nº 109, 9 Jun 2026: draft rules submitted to public consultation','2026-09-24','Checked against BOJA. Details will change when the final rules are published.',null,'payment',true,true,70),
('pyme-innova','camara_pyme','Pyme Innova (innovation projects)','Cámara de Comercio de Málaga','chamber','innovation','Up to €5,950 (85% of €7,000)',5950,'closed',null,null,'Expect the next call around March 2027.','You pay the supplier in full, then get 85% back.','A Cámara tutor helps you plan an innovation project, then you get 85% of the cost back.',array['Innovation in products, services or processes','Specialist consultancy and implementation']::text[],array['Finish the project within 6 months.']::text[],array['SME declaration (declaración responsable)','Proof of IAE registration','Last year’s turnover']::text[],array['Apply in the call window on the Cámara e-office.','Free innovation diagnosis by a Cámara tutor.','Choose a supplier, pay 100%, receive 85% back.']::text[],'https://camaramalaga.com/programa-pyme-innova-2026/',null,'2026-09-23','Málaga includes hospitality (IAE group 67). Turnover and IAE-date rules taken from the same programme in other Cámaras.','Eligibility rules were taken from other Cámaras. Verify the Cámara de Málaga’s own 2026 call.','payment',true,false,80),
('pyme-digital','camara_pyme','Pyme Digital (website, e-commerce, digital marketing)','Cámara de Comercio de Málaga','chamber','digital','Up to €5,950 (85% of €7,000)',5950,'closed',null,'2026-03-13','The 2026 call ran 9 to 13 March. Expect the next around March 2027.','You pay the supplier in full, then get 85% back.','A Cámara tutor diagnoses your digital needs, then you get 85% of the project cost back.',array['Website and e-commerce','Digital marketing','Management software']::text[],array['Finish the project within 6 months.']::text[],array['SME declaration (declaración responsable)','Proof of IAE registration','Last year’s turnover']::text[],array['Apply in the March window on the Cámara e-office.','Applications are ordered by a notarised draw.','Free digital diagnosis.','Choose a supplier, pay 100%, receive 85% back.']::text[],'https://camaramalaga.com/programa-pyme-digital-2026/',null,'2026-09-23',null,null,'payment',true,true,81),
('pyme-sostenible','camara_pyme','Pyme Sostenible (energy efficiency, carbon footprint)','Cámara de Comercio de Málaga','chamber','energy','Up to €5,950 (85% of €7,000)',5950,'closed',null,'2026-03-12','The 2026 call ran 6 to 12 March. Expect the next around March 2027.','You pay the supplier in full, then get 85% back.','A Cámara tutor diagnoses your energy use, then you get 85% of the improvement project back.',array['Energy efficiency improvements','Carbon footprint calculation','Circular economy measures']::text[],array['Finish the project within 6 months.']::text[],array['SME declaration (declaración responsable)','Proof of IAE registration','Last year’s turnover']::text[],array['Apply in the March window on the Cámara e-office.','Applications are ordered by a notarised draw.','Free sustainability diagnosis.','Choose a supplier, pay 100%, receive 85% back.']::text[],'https://camaramalaga.com/programa-pyme-sostenible-2026/',null,'2026-09-23',null,null,'payment',true,true,82),
('innovactiva','innovactiva','Innovactiva: young entrepreneurs','Instituto Andaluz de la Juventud','regional','startup','Up to €9,000',9000,'closed',null,'2026-04-05','The 2026 call ran 5 March to 5 April. Expect the next around March 2027.','Competitive. Covers investment only (equipment, fit-out, software), not running costs.','For entrepreneurs aged 18 to 35 starting a business in Andalucía. Projects are scored against each other.',array['Equipment and furniture','Fit-out of premises','Software and computers']::text[],array['Spend on investment items and justify with invoices.']::text[],array['ID and proof of residence in Andalucía','Qualification certificate (ESO or higher)','Business plan and investment budget']::text[],array['Watch BOJA for the next call.','Apply online within the window (about one month).','Projects are scored and ranked.','Buy the investment items and justify with invoices.']::text[],'https://juntadeandalucia.es/boja/2026/44/3',null,'2026-09-23',null,null,'payment',true,true,90),
('diputacion-6000','diputacion_6000','Diputación de Málaga grant for autónomos in small towns','Diputación de Málaga','provincial','autonomo','€6,000 towards your autónomo quota',6000,'closed',null,'2026-05-12','The 2026 call ran 28 April to 12 May. Watch for 2027.','One payment of €6,000, justified by staying registered as autónomo and in the IAE.','€6,000 for autónomos who live and work in a town under 20,000 people in Málaga province. Competitive: priority groups and newer autónomos score higher.',array['Your autónomo quota for the year']::text[],array['Live and work in a town under 20,000 people, registered on its padrón for at least a year before the call.','2026 call: registered as autónomo (RETA) between 1 Jan 2022 and 1 Jan 2026, without interruption.','Keep the activity going for the required period and justify it afterwards.']::text[],array['Digital certificate or Cl@ve','Proof of registration as autónomo','Proof of residence and business in the town']::text[],array['Watch the Boletín Oficial de la Provincia de Málaga in spring.','Apply within the 10 working days of the call.']::text[],'https://www.malaga.es/empleo/1420/com1_md2_cd-63160/subvenciones-destinadas-a-apoyar-el-emprendimiento-y-la-consolidacion-del-empleo-autonomo-de-municipios-menores-de-20-000-habitantes-de-la-provincia-de-malaga-2026','BOP Málaga nº 79, 27 Apr 2026 (CVE 20260427-01551-2026)','2026-09-24','Checked against the BOP Málaga and the Diputación’s official page.',null,'payment',true,true,95),
('fundae','fundae','FUNDAE training credit','FUNDAE (Fundación Estatal para la Formación en el Empleo)','national','training','At least €420 a year for companies with 1 to 5 employees',420,'permanent',null,null,null,'Recovered as a discount on Social Security payments after the training.','Every company with staff has a yearly training budget, recovered as a Social Security discount. Unused credit carries over for up to 2 years.',array['Staff training: barista skills, food handling, languages, customer service']::text[],array['Notify each course at least 2 days before it starts.']::text[],array['Company digital certificate','Registration in the FUNDAE application']::text[],array['Register the company in the FUNDAE application.','Choose training (barista, food handling, languages).','Notify the course start at least 2 days before.','Deduct the cost from Social Security payments afterwards.']::text[],'https://www.fundae.es/empresas/home/como-bonificarte/bonificaci%C3%B3n-acciones-programadas',null,'2026-09-24','Not a grant to apply for: a credit every company with employees already has.',null,'payment',false,true,110),
('tarifa-plana','tarifa_plana','Tarifa plana (reduced autónomo quota)','Seguridad Social','national','autonomo','€80 a month instead of the full quota for 12 months',0,'permanent',null,null,null,'Not a payment: a reduced monthly quota, with a second year if income stays under the minimum wage.','New autónomos pay a reduced €80 a month for their first year instead of the full quota.',array['Your first 12 months of Social Security']::text[],'{}'::text[],array['Autónomo registration through Import@ss']::text[],array['Request it in the same process as your autónomo registration.']::text[],'https://www.seg-social.es',null,'2026-09-23',null,null,'payment',false,true,120),
('pago-unico','pago_unico','Pago único (capitalising unemployment benefit)','SEPE','national','startup','Your remaining unemployment benefit as one payment',0,'permanent',null,null,null,'Paid as one sum to start the business.','If you receive unemployment benefit, you can take what’s left as one payment to start your business.',array['Start-up investment or your first months of Social Security']::text[],'{}'::text[],array['Application to SEPE','Description of the business project']::text[],array['Apply to SEPE before registering as autónomo.','Once approved, register and start trading.']::text[],'https://www.sepe.es',null,null,'Not yet verified by us.','Not yet checked against SEPE’s official page.','payment',true,false,130);
insert into public.document_types (id, name, how_to_get, kind, stage, template_key, official_url, we_can_prepare, sort_order) values
('cert_digital','Digital certificate or Cl@ve for the legal representative','Companies need a representative certificate from the FNMT. Autónomos can use a personal certificate or Cl@ve. Also install AutoFirma to sign.','credential','apply',null,'https://www.sede.fnmt.gob.es',false,1),
('kit_test','Acelera Pyme digital self-assessment','A short online test on Acelera Pyme. Required before applying for Kit Digital.','online','apply',null,'https://www.acelerapyme.gob.es',false,2),
('rep_auth','Authorisation for us to apply for you','Download our template, sign it and upload it. Or grant it online in the government’s REA register (apoderamiento).','form','apply','representacion',null,false,10),
('kit_annex2','Kit Digital representative authorisation (Anexo II)','Official Red.es form. Sign it and upload it.','form','apply',null,'https://sede.red.gob.es/es/procedimientos/convocatoria-de-ayudas-destinadas-la-digitalizacion-de-empresas-del-segmento-iii',false,11),
('memoria_equipos','Project description with the energy saving (memoria descriptiva)','Lists the equipment you replace, the new models and the saving. Use the Ministry’s official models if available; our template follows the same structure.','form','apply','memoria_equipos','https://www.mintur.gob.es/PortalAyudas/EquiposHosteleria/Solicitudes/Guias%20y%20modelos/Guia_Solicitante.pdf',true,12),
('memoria_proyecto','Project description (memoria del proyecto)','What you will do, why, the budget and the timeline.','form','apply','memoria_proyecto',null,true,13),
('viability_plan','Business and viability plan with a 3-year profit forecast','Shows your business idea, start-up investment and a profit-and-loss forecast. For Línea 2 every year must show a profit.','form','apply','plan_viabilidad',null,true,14),
('minimis_decl','De minimis aid declaration','Lists any other small state aid received in the last 3 years. Fill in, sign and upload.','form','apply','minimis',null,false,15),
('pyme_decl','SME declaration (declaración responsable de PYME)','Confirms your staff numbers and turnover. Fill in, sign and upload.','form','apply','pyme',null,false,16),
('camara_anexos','Cámara application forms (anexos de solicitud)','Official forms on the Cámara de Málaga page for this grant. Fill in, sign and upload.','form','apply',null,null,false,17),
('id_doc','ID of the legal representative (DNI or NIE)','A clear photo or scan of both sides.','upload','apply',null,null,false,20),
('escrituras','Company deeds and proof of the director’s appointment','Escrituras de constitución and nombramiento de administrador. Your notary or gestor has them.','upload','apply',null,null,false,21),
('cert_censal','Tax registration certificate (certificado de situación censal)','Free and instant from the Agencia Tributaria e-office. Shows your activity (IAE) and start date.','upload','apply',null,'https://sede.agenciatributaria.gob.es',false,22),
('cnae_proof','Official document showing your CNAE code','Your last corporate tax return (Modelo 200), or the Social Security “Informe de situación de código de cuenta de cotización”. Must show CNAE 55 or 56.','upload','apply',null,null,false,23),
('cert_aeat','Certificate of being up to date with Hacienda','Agencia Tributaria e-office: “Certificado de estar al corriente de obligaciones tributarias”. Usually instant.','upload','apply',null,'https://sede.agenciatributaria.gob.es',false,24),
('cert_ss','Certificate of being up to date with Social Security','Import@ss or the Social Security e-office: “Certificado de estar al corriente”.','upload','apply',null,'https://www.seg-social.es',false,25),
('bank_cert','Bank account ownership certificate (certificado de titularidad)','Download it from your online banking or ask your branch. The account must be in the applicant’s name.','upload','apply',null,null,false,26),
('reta_alta','Proof of autónomo registration (alta en RETA)','Import@ss: “Informe de situación actual” or your registration resolution.','upload','apply',null,'https://www.seg-social.es',false,27),
('padron','Certificate of registration on the padrón (empadronamiento)','From your town hall, often available online.','upload','apply',null,null,false,28),
('qualification','Qualification certificate (ESO or higher)','Your school or university certificate, or the official title.','upload','apply',null,null,false,29),
('turnover_proof','Proof of last year’s turnover','Last corporate tax return (Modelo 200) or annual VAT summary (Modelo 390).','upload','apply',null,null,false,30),
('equipment_quote','Detailed quote or invoice for the new equipment','From your supplier, showing each model, its energy class and prices without IVA.','upload','apply',null,null,false,31),
('energy_saving','Proof of the energy saving','EU energy labels of the old and new equipment, or a technician’s comparison report where there is no label.','upload','apply',null,null,false,32),
('quotes','Quotes (presupuestos) for the project','From your suppliers, with prices excluding IVA.','upload','apply',null,null,false,33),
('energy_cert_before','Energy certificate of the premises before the works','From a qualified technician (arquitecto or ingeniero).','upload','apply',null,null,false,34),
('rta_cert','Registro de Turismo de Andalucía registration','Proof your business is in the Andalusian tourism register.','upload','apply',null,null,false,35),
('contract','Signed full-time employment contract (6 months or more)','Registered through Contrat@, usually by your gestor.','upload','apply',null,null,false,36),
('worker_joven','Proof the new hire is in Garantía Juvenil and on Talento Joven','The Cámara provides this for candidates on the programme.','upload','apply',null,null,false,37),
('worker_45','Proof the new hire is a Talento 45+ participant','The Cámara provides this for candidates on the programme.','upload','apply',null,null,false,38),
('invoices_payments','Paid invoices and bank proof of each payment','Keep every invoice and the bank transfer that paid it. Cash payments usually don’t count.','upload','after',null,null,false,50),
('waste_cert','Certificate from an authorised waste manager for the old equipment','Your supplier or installer usually arranges this.','upload','after',null,null,false,51),
('payroll_proof','Payslips and Social Security payment receipts for the new hire','Your gestor produces these monthly.','upload','after',null,null,false,52);
